// Regenerates src/types/database.ts from the LOCAL Supabase schema.
// Never points at the hosted project.
import { execSync } from "node:child_process";
import { writeFileSync } from "node:fs";

// Constant command (no user input); the CLI targets the local stack by default.
const output = execSync("npx --yes supabase@3.2.0 gen types typescript --schema public", {
  encoding: "utf8",
  stdio: ["ignore", "pipe", "inherit"],
});

const header = [
  "// Generated by `pnpm db:types` from the LOCAL Supabase schema. Do not edit by hand.",
  "// Note: the generator marks RPC result columns as non-null; employee DTO parsers",
  "// in src/features/employees/dto.ts apply the real nullability at runtime.",
  "",
  "",
].join("\n");

const body = output.replace(/^﻿/, "").replace(/\r\n/g, "\n").replace(/^\s*\n/, "");
writeFileSync(new URL("../src/types/database.ts", import.meta.url), header + body);
console.log("Wrote src/types/database.ts");
